def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Mark monochrome rectangular fields at least 5 by 5.
    for top in range(h):
        common = [True] * w
        for bottom in range(top, h):
            if bottom > top:
                prev = grid[bottom - 1]
                cur = grid[bottom]
                common = [ok and prev[c] == cur[c] for c, ok in enumerate(common)]
            if bottom - top + 1 < 5:
                continue
            c = 0
            while c < w:
                if not common[c]:
                    c += 1
                    continue
                d = c + 1
                while d < w and common[d] and grid[top][d] == grid[top][c]:
                    d += 1
                if d - c >= 5:
                    for r in range(top, bottom + 1):
                        for x in range(c, d):
                            out[r][x] = 4
                c = d
    return out

